with flattened_attrs as (select id, service, host, latency_ms, context, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier as tier, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec, context['trace'] as trace, context['region'] as region from app_logs) select case when duration_sec >= 4.3 then 'LARGE' else 'SMALL' end as duration_sec_tier, percentile_approx(duration_sec, 0.95) as duration_sec_p95, avg(latency_ms) filter (where host = 'h3') as h3_avg_latency_ms, round(sum(latency_ms) / nullif(count(case when host = 'h3' then 1 end), 0), 2) as latency_ms_per_h3, bit_or(latency_ms) as latency_ms_bit_or, bit_and(latency_ms) as latency_ms_bit_and from flattened_attrs group by case when duration_sec >= 4.3 then 'LARGE' else 'SMALL' end order by duration_sec_tier desc;
